import re
with open('doc/superhero.md') as f:
    c=f.read()
parts=c.split('\n\n')
# Extract all identifiers with their heights (from biometric sections)
id_height={}
for part in parts:
    if 'height' in part.lower() and 'publisher' not in part.lower():
        m=re.search(r'(\d+\.?\d*)\s*centimeters', part, re.I)
        if m:
            ht=float(m.group(1))
            idm=re.search(r'(?:(?:identifier|registry|reference|file under|registry under|file under ID)\s*(?:\w*\s*)?(\d+))', part, re.I)
            if idm:
                idx=idm.group(1)
                if 150<=ht<=180:
                    id_height[idx]=ht
print(f'Found {len(id_height)} heroes with height 150-180')
# Now extract publisher info by identifier
id_pub={}
for part in parts:
    if 'publisher' in part.lower():
        pubm=re.search(r'publisher\s+(\d+)', part, re.I)
        if pubm:
            pid=pubm.group(1)
            idm=re.search(r'(?:(?:identifier|registry|reference|file under|registry under|file under ID)\s*(?:\w*\s*)?(\d+))', part, re.I)
            if idm:
                idx=idm.group(1)
                id_pub[idx]=pid
print(f'Found {len(id_pub)} heroes with publisher info')
# Cross-reference
marvel_count=0
total_count=0
for idx in id_height:
    if idx in id_pub:
        total_count+=1
        if id_pub[idx]=='13':
            marvel_count+=1
print(f'Total matches: {total_count}, Marvel: {marvel_count}')
print(f'Percentage: {round(100*marvel_count/total_count,2) if total_count else "N/A"}%')

